<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');$data=$_SESSION['kwitansi_import']??null;$kid=(int)($_GET['id']??0);if(!$data||(int)$data['id_kegiatan']!==$kid){flash('warning','Sesi preview tidak tersedia. Upload ulang file.');redirect('/admin/kwitansi/excel.php?id='.$kid);}page_header('Preview Import Kwitansi');?><div class="card p-4"><div class="d-flex justify-content-between"><h2 class="h5 fw-bold">Preview Data Kwitansi</h2><a class="btn btn-light" href="<?=APP_BASE_URL?>/admin/kwitansi/excel.php?id=<?=$kid?>">Upload Ulang</a></div><p>Baris valid: <strong><?=count($data['rows'])?></strong> · Kesalahan: <strong><?=count($data['errors'])?></strong></p><?php if($data['errors']):?><div class="alert alert-danger"><strong>Perbaiki file sebelum konfirmasi:</strong><ul class="mb-0"><?php foreach($data['errors'] as $err):?><li><?=e($err)?></li><?php endforeach;?></ul></div><?php endif;?><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Baris</th><th>Tanggal</th><th>Petugas</th><th>Nomor ST</th><th>Nominal</th><th>Hal</th><th>Bulan Pengajuan</th></tr></thead><tbody><?php foreach($data['rows'] as $r):?><tr><td><?=$r['baris']?></td><td><?=format_tanggal($r['tanggal'])?></td><td><?=e($r['nama_petugas'])?></td><td><?=e($r['nomor_surat_tugas'])?></td><td>Rp <?=number_format($r['nominal'],0,',','.')?></td><td><?=e($r['keperluan'])?></td><td><?=e($r['bulan_pengajuan_kwitansi'])?></td></tr><?php endforeach;?></tbody></table></div><form method="post" action="<?=APP_BASE_URL?>/admin/kwitansi/confirm_import.php"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id_kegiatan" value="<?=$kid?>"><button class="btn btn-primary" <?=$data['errors']||!$data['rows']?'disabled':''?>>Konfirmasi dan Simpan</button></form></div><?php page_footer();
